My tide lookup page works but it feels rough and I want to put it in front of the harbor club members on Friday. Can you make it feel finished? Keep it one self-contained HTML file, inline CSS and JS, system fonts, nothing loaded from outside. Here is what I have:

<!doctype html>
<html><head><title>Tide lookup</title>
<style>
body{font-family:sans-serif;margin:20px}
input,button{font-size:16px;padding:6px}
table{border-collapse:collapse;margin-top:16px}
td,th{border:1px solid #ccc;padding:4px 10px}
</style></head><body>
<h1>Tide lookup</h1>
<input id="port" placeholder="Port name">
<button onclick="go()">Search</button>
<div id="out"></div>
<script>
const DATA={"Kellmouth":[["04:12","High","4.1 m"],["10:30","Low","0.6 m"],["16:44","High","4.3 m"],["22:51","Low","0.5 m"]],"Port Arnley":[["05:02","High","3.2 m"],["11:19","Low","0.9 m"]]};
function go(){
  const p=document.getElementById('port').value;
  const rows=DATA[p]||[];
  let h='<table><tr><th>Time</th><th>Tide</th><th>Height</th></tr>';
  rows.forEach(r=>{h+='<tr><td>'+r[0]+'</td><td>'+r[1]+'</td><td>'+r[2]+'</td></tr>'});
  document.getElementById('out').innerHTML=h+'</table>';
}
</script></body></html>

